import { mkdirSync, readFileSync, writeFileSync } from "node:fs";

mkdirSync(new URL("../public/", import.meta.url), { recursive: true });

for (const [theme, filename] of [
  ["light", "favicon.svg"],
  ["dark", "favicon-dark.svg"],
]) {
  const logo = readFileSync(
    new URL(`../../../packages/brand/assets/logo-${theme}.svg`, import.meta.url),
    "utf8",
  ).trim();

  const favicon = `<svg xmlns="http://www.w3.org/2000/svg" width="512" height="512" viewBox="0 0 512 512">
  <!-- Generated by scripts/generate-brand-assets.mjs. Web-only rounding; the packaging source stays square. -->
  <defs>
    <clipPath id="site-icon-corners">
      <rect width="512" height="512" rx="112"/>
    </clipPath>
  </defs>
  <g clip-path="url(#site-icon-corners)">
${logo}
  </g>
</svg>
`;

  writeFileSync(new URL(`../public/${filename}`, import.meta.url), favicon, "utf8");
  console.log(`Generated public/${filename} from the ${theme} brand logo`);
}